'use strict';
let COURSE=window.COURSE;const config=window.CYBER_CONFIG,$=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shield='<svg viewBox="0 0 100 100" fill="none" aria-hidden="true"><defs><mask id="cut"><rect width="100" height="100" fill="white"/><path d="M5 76 L33 45 L29 63 L8 91Z" fill="black"/></mask></defs><g mask="url(#cut)"><path d="M78.3 21.7 A40 40 0 1 0 78.3 78.3" fill="none" stroke="currentColor" stroke-width="17"/></g><path d="M37 49 L47 59 L66 39" fill="none" stroke="currentColor" stroke-width="9" stroke-linecap="round" stroke-linejoin="round"/></svg>';
const G='<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="#4285F4" d="M22.6 12.2c0-.7-.1-1.4-.2-2.1H12v4h5.9a5 5 0 0 1-2.2 3.2v2.6h3.6c2.1-1.9 3.3-4.6 3.3-7.7Z"/><path fill="#34A853" d="M12 23c3 0 5.5-1 7.3-2.7l-3.6-2.9c-1 .7-2.2 1-3.7 1-2.9 0-5.3-1.9-6.2-4.5H2.1v2.9A11 11 0 0 0 12 23Z"/><path fill="#FBBC05" d="M5.8 13.9a6.7 6.7 0 0 1 0-4.2V6.8H2.1a11 11 0 0 0 0 10l3.7-2.9Z"/><path fill="#EA4335" d="M12 5.2c1.6 0 3 .5 4.1 1.6l3.1-3.1A10.5 10.5 0 0 0 12 1a11 11 0 0 0-9.9 5.8l3.7 2.9C6.7 7.1 9.1 5.2 12 5.2Z"/></svg>';
let user=null,authAPI=null,authReady=false,storageOK=true,activeKey='cyber-reflexes-v2:guest',toastTimer;
const configured=Boolean(config.firebase?.apiKey&&config.firebase?.authDomain&&config.firebase?.projectId&&config.firebase?.appId);
const blank=()=>({completedAt:"",participantName:"",version:2,completed:[],current:0,answers:{},read:[],revealed:[],lessonSteps:{},practiceAnswers:{}});
function normalize(v){if(!v||v.version!==2||!Array.isArray(v.completed))throw Error('invalid');let n=0;while(n<24&&v.completed.includes(n))n++;const answers={};for(let i=0;i<24;i++){if(Array.isArray(v.answers?.[i]))answers[i]=v.answers[i].slice(0,3).map(a=>a===0||a===1?a:null)}const lessonSteps={},practiceAnswers={};for(let i=0;i<24;i++){if(Number.isInteger(v.lessonSteps?.[i])&&v.lessonSteps[i]>=0&&v.lessonSteps[i]<6)lessonSteps[i]=v.lessonSteps[i];if(v.practiceAnswers?.[i]===0||v.practiceAnswers?.[i]===1)practiceAnswers[i]=v.practiceAnswers[i]}return{completedAt:validCompletionDate(v.completedAt),participantName:typeof v.participantName==="string"?v.participantName.slice(0,80):"",lessonSteps,practiceAnswers,version:2,completed:Array.from({length:n},(_,i)=>i),current:Math.min(n,23,Number.isInteger(v.current)?Math.max(0,v.current):n),answers,read:Array.isArray(v.read)?v.read.filter(i=>Number.isInteger(i)&&i>=0&&i<=n&&i<24):[],revealed:Array.isArray(v.revealed)?v.revealed.filter(i=>Number.isInteger(i)&&i>=0&&i<=n&&i<24):[]}}
function load(){try{let raw=localStorage.getItem(activeKey);return raw?normalize(JSON.parse(raw)):blank()}catch(e){storageOK=false;return blank()}}
let state=load();function save(){try{localStorage.setItem(activeKey,JSON.stringify(state));storageOK=true;window.ProgressSync?.changed()}catch(e){storageOK=false;notify('La sauvegarde automatique est indisponible. Exportez votre progression avant de quitter.')}}
function notify(message){$('#toast').textContent=window.CyberExperience?.text(message)||message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,6500)}
function themeButton(){const dark=document.documentElement.dataset.theme==='dark';return `<button class="theme-toggle" type="button" data-theme-toggle aria-label="${dark?'Activer le mode clair':'Activer le mode sombre'}" aria-pressed="${dark}"><span aria-hidden="true">${dark?'☀':'◐'}</span><span>${dark?'Mode clair':'Mode sombre'}</span></button>`}
function setTheme(theme){try{localStorage.setItem('cyberilo-theme-preference',theme)}catch{}document.documentElement.dataset.theme=theme;try{localStorage.setItem('cyber-reflexes-theme',theme)}catch(e){}document.querySelector('meta[name="theme-color"]').content=theme==='dark'?'#131C25':'#F5F7F9';document.querySelectorAll('[data-theme-toggle]').forEach(b=>{const dark=theme==='dark';b.setAttribute('aria-pressed',dark);b.setAttribute('aria-label',dark?'Activer le mode clair':'Activer le mode sombre');b.innerHTML=`<span aria-hidden="true">${dark?'☀':'◐'}</span><span>${dark?'Mode clair':'Mode sombre'}</span>`})}
const brand=()=>`<a class="brand" href="#/">${shield}<div>Cyberilo</div></a>`;
const author=()=>{const name=esc(config.author||'Oumar Bocoum');try{const url=new URL(config.authorLinkedIn);if(url.protocol==='https:'&&['linkedin.com','www.linkedin.com'].includes(url.hostname)&&url.pathname.startsWith('/in/'))return `<a class="author-link" href="${esc(url.href)}" target="_blank" rel="noopener noreferrer" aria-label="${name} — profil LinkedIn (nouvel onglet)">${name}</a>`}catch(e){}return name};
function header(){const en=document.documentElement.lang==='en',tr=(fr,eng)=>en?eng:fr;return `<header class="site-header">${brand()}<nav class="site-nav" aria-label="${tr('Navigation principale','Main navigation')}"><a href="#/catalogue">${tr('Les formations','Courses')}</a><a href="#/a-propos">${tr('À propos','About')}</a>${themeButton()}<button class="account-btn" data-account>${user?esc(user.displayName||tr('Mon espace','My learning')):tr('Se connecter','Sign in')}</button><button class="mobile-nav-toggle" id="mobileNavToggle" aria-controls="mobileSiteNav" aria-expanded="false" aria-label="${tr('Ouvrir le menu','Open menu')}">☰</button></nav><nav class="mobile-site-nav" id="mobileSiteNav" hidden aria-label="${tr('Menu mobile','Mobile navigation')}"><a href="#/catalogue">${tr('Les formations','Courses')}</a>${user?`<a href="#/espace">${tr('Mon espace','My learning')}</a><a href="#/formations">${tr('Mes formations','My courses')}</a>`:`<a href="#/compte">${tr('Se connecter','Sign in')}</a>`}<a href="#/a-propos">${tr('À propos de Cyberilo','About Cyberilo')}</a><a href="#/contact">Contact</a><div class="mobile-preferences">${themeButton()}${window.CyberExperience?.languageControl?.()||''}</div></nav></header>`}

function footer(){const en=document.documentElement.lang==='en';return `<footer class="footer"><div><b>Cyberilo</b><p class="small">${en?'Understand. Practise. Stay safer.':'Comprendre. Pratiquer. Mieux se protéger.'}</p></div><div class="row"><a href="#/catalogue">${en?'Courses':'Formations'}</a><a href="#/a-propos">${en?'About':'À propos'}</a><a href="#/contact">Contact</a><a href="#/confidentialite">${en?'Privacy':'Confidentialité'}</a><a href="#/aide">${en?'Help':'Aide'}</a>${user&&state.completed.length>=COURSE.length?`<a href="#/avis">${en?'My feedback':'Mon avis'}</a>`:''}</div></footer>`}

function utilities(){return `<div class="utility"><button class="link-btn" data-export>Exporter ma progression</button><button class="link-btn" data-import>Importer une sauvegarde</button><button class="link-btn" data-reset>Recommencer</button></div><p class="small">${storageOK?'Copie locale conservée. Avec Google, votre progression se retrouve sur vos appareils.':'Sauvegarde automatique indisponible : exportez votre progression avant de quitter.'}</p>`}
