 c.textAlign='center';c.fillStyle='#2F5D7C';c.font='600 18px "Segoe UI", Arial, sans-serif';c.fillText(window.CyberPlatform.get(window.CyberPlatform.current()).title[document.documentElement.lang==='en'?'en':'fr'],800,367,1280);c.fillStyle='#244A63';c.font='600 52px "Segoe UI", Arial, sans-serif';c.fillText(window.CyberExperience.text("Un clic de recul.","Pause before you click."),800,448);c.fillText(window.CyberExperience.text("Un pas de plus pour se protéger.","One step closer to staying safe."),800,514);
