function about(){infoPage('Comprendre les pièges. Protéger les gens.',`<div class="about-intro"><span class="eyebrow">À PROPOS DE CYBERILO</span><p>Cyberilo propose des formations courtes et gratuites pour comprendre les risques numériques et adopter des gestes utiles. Deux parcours sont disponibles : les bases de la sécurité numérique et la protection des comptes au quotidien, en français et en anglais.</p><p>Un message peut ressembler à celui d’un proche. Un faux site peut paraître officiel. Face à ces situations, chacun mérite des explications simples et des gestes qu’il peut appliquer.</p></div><h2>Une initiative pour notre communauté</h2><p>Cyberilo est un guide gratuit de sensibilisation aux risques numériques. Son objectif est de rendre les bases de la cybersécurité accessibles aux particuliers, aux familles et aux personnes qui souhaitent mieux se protéger dans leur vie professionnelle.</p><p>Le parcours aborde les messages frauduleux, les liens, les QR codes, les fichiers et la protection des comptes. Les exemples sont proches du quotidien, notamment les demandes d’argent entre proches, les faux recrutements et les arnaques Mobile Money.</p><div class="about-values"><article><span>01</span><h3>Comprendre sans jargon</h3><p>Des explications claires, sans connaissances techniques préalables.</p></article><article><span>02</span><h3>Apprendre en essayant</h3><p>Des situations concrètes, des messages clés et des réponses expliquées.</p></article><article><span>03</span><h3>Transmettre autour de soi</h3><p>Un réflexe compris peut devenir un conseil utile à un proche.</p></article></div><h2>À l’initiative du guide</h2><div class="author-profile"><div class="author-avatar" aria-hidden="true">OB</div><div><h3>${author()}</h3><p>Ingénieur en génie informatique, professionnel de la donnée et du développement web.</p><p>« J’ai voulu proposer un espace simple pour comprendre les arnaques numériques et apprendre à protéger ses comptes, son argent et ses proches. »</p></div></div><h2>Notre façon de travailler</h2><p>Les modules associent une situation, des explications, des gestes à retenir et un quiz. Les références sont présentées en texte simple dans la page des repères pédagogiques. Les signalements et les avis des participants servent à identifier les contenus à améliorer.</p><h2>Le rôle de ce guide</h2><p>Cyberilo est une initiative de sensibilisation indépendante. Le bilan atteste d’un suivi pédagogique dans le site ; il ne constitue pas une certification professionnelle ni une prestation d’assistance en cas de piratage.</p><div class="row"><a class="btn" href="#/">Découvrir le parcours →</a><a class="btn light" href="#/contact">Nous contacter</a></div>`)}
const readDraft=key=>{try{const v=JSON.parse(localStorage.getItem(key)||'{}');return v&&typeof v==='object'&&!Array.isArray(v)?v:{}}catch(e){return{}}};
function saveDraft(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch(e){notify('Votre navigateur ne permet pas de sauvegarder ce brouillon. Gardez-en une copie avant de quitter.')}}
function exportText(name,text){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function contact(){
 const email=typeof config.contactEmail==='string'&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(config.contactEmail)?config.contactEmail:'';
 const draft=readDraft('cyberilo-contact:'+activeKey);
 infoPage('Une question, une idée, une correction ?',`<p>Vous avez repéré une explication peu claire, une erreur ou un problème sur le site ? Votre message peut nous aider à améliorer le guide.</p><div class="contact-note"><b>En cas de compte piraté ou d’argent transféré</b><p>Utilisez en priorité les canaux officiels de votre banque, de votre opérateur ou du service concerné. Ce formulaire n’est pas un service d’assistance d’urgence.</p><a class="link-btn" href="#/aide">Consulter les premiers réflexes</a></div><section class="form-panel"><span class="eyebrow">CONTACTER L’AUTEUR</span><h2>Préparer votre message</h2><p class="small">${email?'Le bouton ouvrira votre messagerie. Vous pourrez vérifier le contenu avant de l’envoyer.':'La réception des messages n’est pas encore activée. Vous pouvez préparer un brouillon et le télécharger ; aucun message ne sera envoyé.'}</p><form id="contactForm"><label for="contactTopic">Votre demande</label><select id="contactTopic"><option value="question">Une question sur le guide</option><option value="correction">Signaler une erreur dans un contenu</option><option value="technique">Signaler un problème technique</option><option value="suggestion">Proposer une amélioration</option><option value="organisation">Échanger pour une organisation</option></select><label for="contactName">Votre nom <span>(facultatif)</span></label><input id="contactName" maxlength="80" autocomplete="name" value="${esc(typeof draft.name==='string'?draft.name.slice(0,80):'')}"><label for="contactMessage">Votre message</label><textarea id="contactMessage" maxlength="2000" minlength="10" rows="7" required placeholder="Expliquez votre demande. Pour signaler une erreur, indiquez le module et l’étape concernés.">${esc(typeof draft.message==='string'?draft.message.slice(0,2000):'')}</textarea><p class="small">Ne partagez aucun mot de passe, code SMS, numéro de compte ou document personnel. Le brouillon est conservé sur ce navigateur jusqu’à son effacement.</p><div class="row"><button type="submit" class="btn">${email?'Ouvrir ma messagerie':'Télécharger mon brouillon'}</button><button type="button" class="link-btn" id="clearContact">Effacer le brouillon</button></div></form><p id="contactStatus" class="form-status" role="status"></p></section>`);
 const form=$('#contactForm');if(['question','correction','technique','suggestion','organisation'].includes(draft.topic))$('#contactTopic').value=draft.topic;
 const value=()=>({topic:$('#contactTopic').value,name:$('#contactName').value.trim(),message:$('#contactMessage').value.trim()});form.oninput=()=>saveDraft('cyberilo-contact:'+activeKey,value());form.onchange=form.oninput;
 form.onsubmit=e=>{e.preventDefault();const v=value();saveDraft('cyberilo-contact:'+activeKey,v);const label=$('#contactTopic').selectedOptions[0].textContent;const body=`Sujet : ${label}\nNom : ${v.name||'Non renseigné'}\n\n${v.message}`;if(email){location.href='mailto:'+email+'?subject='+encodeURIComponent('Cyberilo — '+label)+'&body='+encodeURIComponent(body);$('#contactStatus').textContent='Votre messagerie a été sollicitée. Le message ne sera envoyé que si vous le confirmez dans votre application e-mail.'}else{exportText('cyberilo-message.txt',body);$('#contactStatus').textContent='Brouillon téléchargé. Aucun message n’a été envoyé.'}};
 $('#clearContact').onclick=()=>{form.reset();$('#contactName').value='';$('#contactMessage').value='';try{localStorage.removeItem('cyberilo-contact:'+activeKey)}catch(e){}$('#contactStatus').textContent='Brouillon effacé sur ce navigateur.'}
}
function feedback(){location.hash='/avis'}
function render(){window.CyberAudio?.stop();if(window.CyberExperience?.route())return;document.body.classList.remove("sidebar-is-open");const hash=location.hash;if(hash.startsWith('#/module/')){const match=hash.match(/^#\/module\/(\d{1,2})$/);if(match&&+match[1]<COURSE.length)course(+match[1]);else home()}else if(hash==='#/a-propos')about();else if(hash==='#/contact')contact();else if(hash==='#/avis')feedback();else if(hash==='#/bilan')completion();else if(hash==='#/reussite'||hash.startsWith('#/reussite?'))completion(true);else if(hash==='#/compte')account();else if(hash==='#/sources')sources();else if(hash==='#/confidentialite')privacy();else if(hash==='#/aide')help();else home();window.CyberExperience?.enhance()}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();initAuth();

